pub fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut chars = txt.chars();

    let last = match chars.next_back() {
        None => return false, // empty
        Some(c) => c,
    };

    if !last.is_ascii_alphabetic() {
        return false;
    }

    match chars.next_back() {
        None => true,            // exactly one character
        Some(prev) => prev == ' ' // preceding character must be a space
    }
}